/**
 * Exact text measurement for creatives, from the fonts' own advance widths
 * (assets/fonts/metrics.json, generated by scripts/font-metrics.py).
 *
 * The renderer breaks every line itself from these measurements and draws
 * each line unwrapped, so what is measured is what is drawn: a headline is
 * sized to fit its box, never cropped and never overlapping what follows.
 * Pure — the metrics are passed in.
 */

export type FontMetrics = Record<
  string,
  { unitsPerEm: number; advances: Record<string, number> }
>;

export interface FitOptions {
  /** Font files in fallback order (a glyph missing from one is taken from the next). */
  fonts: string[];
  maxWidth: number;
  maxHeight: number;
  maxSize: number;
  minSize: number;
  lineHeight: number;
  maxLines?: number;
  /** Tracking in em (e.g. 0.02). */
  letterSpacing?: number;
}

export interface Fitted {
  size: number;
  lines: string[];
  width: number;
  height: number;
}

/** Kerning and rendering differences are absorbed by measuring slightly wide. */
const SAFETY = 1.04;

function advance(metrics: FontMetrics, fonts: string[], ch: string): number {
  const cp = String(ch.codePointAt(0));
  for (const f of fonts) {
    const m = metrics[f];
    const a = m?.advances[cp];
    if (m && a !== undefined) return a / m.unitsPerEm;
  }
  // Unknown glyph: a wide default, so it is never under-measured.
  return 0.62;
}

/** Width of `text` at `size` px. */
export function measure(
  metrics: FontMetrics,
  fonts: string[],
  text: string,
  size: number,
  letterSpacing = 0,
): number {
  let w = 0;
  for (const ch of text) w += advance(metrics, fonts, ch) + letterSpacing;
  return w * size * SAFETY;
}

/** Greedy word wrap. Null when a single word is wider than the box. */
export function wrap(
  metrics: FontMetrics,
  fonts: string[],
  text: string,
  size: number,
  maxWidth: number,
  letterSpacing = 0,
): string[] | null {
  const words = text.trim().split(/\s+/).filter(Boolean);
  const lines: string[] = [];
  let current = '';
  for (const word of words) {
    if (measure(metrics, fonts, word, size, letterSpacing) > maxWidth)
      return null;
    const next = current ? `${current} ${word}` : word;
    if (measure(metrics, fonts, next, size, letterSpacing) <= maxWidth)
      current = next;
    else {
      lines.push(current);
      current = word;
    }
  }
  if (current) lines.push(current);
  return lines;
}

/**
 * The largest size (≤ maxSize, ≥ minSize) at which `text` fits the box, with
 * its lines. Null when it cannot fit even at the minimum — the caller must
 * shorten the text, never crop it.
 */
export function fitText(
  metrics: FontMetrics,
  text: string,
  o: FitOptions,
): Fitted | null {
  if (!text.trim()) return { size: o.minSize, lines: [], width: 0, height: 0 };
  for (
    let size = o.maxSize;
    size >= o.minSize;
    size -= Math.max(1, Math.round(size * 0.04))
  ) {
    const lines = wrap(
      metrics,
      o.fonts,
      text,
      size,
      o.maxWidth,
      o.letterSpacing ?? 0,
    );
    if (!lines) continue;
    if (o.maxLines && lines.length > o.maxLines) continue;
    const height = lines.length * size * o.lineHeight;
    if (height > o.maxHeight) continue;
    const width = Math.max(
      ...lines.map((l) =>
        measure(metrics, o.fonts, l, size, o.letterSpacing ?? 0),
      ),
    );
    return { size, lines, width, height };
  }
  return null;
}
